from itertools import permutations, product
from math import factorial
from typing import Tuple

Z2Map = Tuple[Tuple[int, ...], Tuple[int, ...]]

def count_z2maps(m: int, n: int) -> int:
    """Enumerate all Z2-maps S^m -> S^n: an injection {0..m}->{0..n} with signs."""
    if m > n:
        return 0
    total = 0
    for phi in permutations(range(n + 1), m + 1):
        for _ in product((1, -1), repeat=m + 1):
            total += 1
    return total

def formula_count(m: int, n: int) -> int:
    """Closed form (n+1)!/(n-m)! * 2^(m+1) for m<=n, else 0."""
    if m > n:
        return 0
    return factorial(n + 1) // factorial(n - m) * 2 ** (m + 1)

if __name__ == "__main__":
    for n in range(5):
        for m in range(n + 1):
            e, f = count_z2maps(m, n), formula_count(m, n)
            assert e == f, (m, n, e, f)
            print(f"#(S^{m} -> S^{n}) = {e}")
    print("Enumeration matches the closed form (n+1)!/(n-m)! * 2^(m+1).")

from typing import Tuple

Z2Map = Tuple[Tuple[int, ...], Tuple[int, ...]]

def is_injective(phi: Tuple[int, ...]) -> bool:
    return len(set(phi)) == len(phi)

def suspension(F: Z2Map, n: int) -> Z2Map:
    """Suspend F : S^m -> S^n to susp(F) : S^{m+1} -> S^{n+1} by adjoining a pole."""
    phi, sigma = F
    return (phi + (n + 1,), sigma + (1,))

def coindex_witness_tower(depth: int) -> None:
    """Start from the identity S^0->S^0 and suspend repeatedly, printing coindex."""
    F: Z2Map = ((0,), (1,))   # S^0 -> S^0
    n = 0
    for k in range(depth):
        m = len(F[0]) - 1
        assert is_injective(F[0]), "suspension must preserve injectivity"
        print(f"level {k}: S^{m} -> S^{n} witnesses coind(S^{n}) >= {m}")
        F = suspension(F, n)
        n += 1

if __name__ == "__main__":
    coindex_witness_tower(6)
    print("Each suspension raises both source and target dimension by exactly one.")

from itertools import permutations, product
from typing import Tuple

Z2Map = Tuple[Tuple[int, ...], Tuple[int, ...]]

def count_z2maps(m: int, n: int) -> int:
    if m > n:
        return 0
    return sum(1 for phi in permutations(range(n + 1), m + 1)
                 for _ in product((1, -1), repeat=m + 1))

def join(F: Z2Map, b: int, G: Z2Map) -> Z2Map:
    """Join F:S^a->S^b and G:S^c->S^d into F*G : S^{a+c+1} -> S^{b+d+1}."""
    phiF, sigF = F
    phiG, sigG = G
    return (phiF + tuple((b + 1) + a for a in phiG), sigF + sigG)

if __name__ == "__main__":
    F: Z2Map = ((0, 1), (1, 1))   # S^1 -> S^1
    G: Z2Map = ((0, 1), (1, 1))   # S^1 -> S^1
    FG = join(F, 1, G)            # S^3 -> S^3
    print("join phi =", FG[0], " (block sum into disjoint ranges, injective)")
    left = count_z2maps(1, 1) ** 2
    right = count_z2maps(3, 3)
    print(f"supermultiplicativity: {left} <= {right} :", left <= right)

