function EXISTS-Z2MAP(m, n):
    return m <= n        # injection of m+1 axes into n+1 slots

function COINDEX-SPHERE(n):
    m <- 0
    while EXISTS-Z2MAP(m + 1, n):
        m <- m + 1
    return m             # = n

function SUSPENSION(F = (phi, sigma), n):
    phi'   <- phi   ++ [n + 1]   # fresh source axis -> fresh target axis
    sigma' <- sigma ++ [+1]      # new pole carries positive sign
    return (phi', sigma')        # a Z2-map S^{m+1} -> S^{n+1}

function JOIN(F = (phiF, sigmaF), b, G = (phiG, sigmaG)):
    high <- [ (b + 1) + a  for a in phiG ]   # shift G's axes past F's range
    phi'   <- phiF   ++ high
    sigma' <- sigmaF ++ sigmaG               # independent signs per block
    return (phi', sigma')                    # a Z2-map S^{a+c+1} -> S^{b+d+1}
